<script lang="ts">
  import { openUrl } from '@tauri-apps/plugin-opener';
  import UiIcon from './UiIcon.svelte';

  const email = 'tomignacio60@gmail.com';
  let message = $state('');
  let notices = $state('');
  let loading = $state(false);
  const credits = [
    { name: 'Forge', url: 'https://files.minecraftforge.net/', detail: 'MinecraftForge y colaboradores. Cargador y marca de sus titulares; la licencia del código no concede por sí sola derechos sobre la marca.' },
    { name: 'Fabric', url: 'https://fabricmc.net/', detail: 'FabricMC y colaboradores. Licencias según cada componente. El contenido del sitio y la marca tienen sus propias condiciones.' },
    { name: 'NeoForge', url: 'https://github.com/neoforged/websites/blob/main/LICENSE.txt', detail: 'NeoForged y colaboradores. Logo sin modificar del repositorio de su sitio: CC BY 4.0, con atribución a NeoForged. Esta licencia de autor no concede derechos de marca. El cargador conserva su licencia independiente.' },
    { name: 'Quilt', url: 'https://github.com/QuiltMC/art/blob/master/brand/LICENSE', detail: 'QuiltMC; arte de marca creado principalmente por Prospector. Icono sin modificar de QuiltMC/art/brand: CC0 1.0 para los derechos de autor; su texto excluye derechos de marca y patentes. No implica afiliación.' },
    { name: 'OptiFine', url: 'https://optifine.net/copyright', detail: 'sp614x. Software propietario: no se incluye en el instalador ni en las exportaciones compartidas de TP LAUNCHER. Las condiciones oficiales restringen su redistribución pública.' },
    { name: 'Modrinth', url: 'https://modrinth.com/legal/terms', detail: 'Rinth, Inc. Plataforma, API y marcas sujetas a sus términos. Los proyectos descargados conservan la licencia de cada autor; el acceso a la API no equivale a una licencia general del logo.' },
    { name: 'CurseForge', url: 'https://support.curseforge.com/support/solutions/articles/9000207405-curseforge-3rd-party-api-terms-and-conditions', detail: 'Overwolf y sus titulares. API y catálogos sujetos al acuerdo de desarrollador y a las restricciones de cada archivo; una clave de API no concede derechos generales sobre marcas o contenidos.' },
    { name: 'Blockbench', url: 'https://www.blockbench.net/wiki/blockbench/logos/', detail: 'JannisX11 y colaboradores. Editor externo; crédito y enlace a su guía pública de logos.' },
    { name: 'NameMC', url: 'https://namemc.com/', detail: 'Catálogo externo de perfiles y skins. Las skins y la marca mantienen los derechos de sus titulares.' },
    { name: 'SkinMC', url: 'https://skinmc.net/', detail: 'Herramientas y catálogo externos. El enlace no concede permiso para redistribuir skins o marcas.' },
    { name: 'MCStacker', url: 'https://mcstacker.net/', detail: 'Generador externo de comandos. Crédito a sus creadores; no se presenta como parte de TP LABS.' },
    { name: 'Chunkbase', url: 'https://www.chunkbase.com/', detail: 'Mapas y herramientas externos, con sus propias condiciones de uso.' },
    { name: 'Planet Minecraft', url: 'https://www.planetminecraft.com/', detail: 'Comunidad externa. Cada mapa, skin o recurso conserva las condiciones de su creador.' },
    { name: 'Minecraft Wiki', url: 'https://minecraft.wiki/', detail: 'Enciclopedia comunitaria. Consulta los créditos y la licencia que acompaña cada texto o imagen.' },
    { name: 'Monocraft', url: 'https://github.com/IdreesInc/Monocraft', detail: 'Idrees Hassan y colaboradores · SIL Open Font License 1.1. Fuente independiente de la tipografía oficial del juego.' },
    { name: 'skinview3d', url: 'https://github.com/bs-community/skinview3d', detail: 'bs-community y colaboradores · MIT. Motor del visor de skins; no constituye una afiliación con otras aplicaciones de poses.' },
    { name: 'Three.js', url: 'https://github.com/mrdoob/three.js/blob/dev/LICENSE', detail: 'Three.js authors · MIT. Biblioteca de renderizado 3D utilizada por el visor.' },
  ];
  async function visit(event: MouseEvent, url: string) {
    event.preventDefault(); message = '';
    try { await openUrl(url); }
    catch { message = `No se pudo abrir el enlace. Dirección: ${url}`; }
  }
  async function copyEmail() {
    try { await navigator.clipboard.writeText(email); message = 'Correo de contacto copiado.'; }
    catch { message = `No se pudo copiar. Correo de contacto: ${email}`; }
  }
  async function loadNotices(event: Event) {
    if (!(event.currentTarget as HTMLDetailsElement).open || notices || loading) return;
    loading = true;
    try {
      const response = await fetch('/legal/THIRD-PARTY-NOTICES.txt');
      if (!response.ok) throw new Error();
      notices = await response.text();
    } catch { notices = 'Consulta legal/THIRD-PARTY-NOTICES.txt en esta distribución o solicita una copia al contacto indicado abajo.'; }
    finally { loading = false; }
  }
</script>

<div class="terms-workspace">
  <header class="terms-heading"><span class="section-symbol"><UiIcon name="shield" size={30}/></span><div><span class="eyebrow">TP LABS · INFORMACIÓN DEL PROYECTO</span><h2>Términos y condiciones</h2><p>Uso del launcher, privacidad, créditos y contacto. Revisión: 27 de octubre de 2026.</p></div></header>
  <div class="independence" role="note"><UiIcon name="info" size={22}/><p><strong>TP LAUNCHER es un proyecto independiente de TP LABS.</strong> No es un producto oficial de Minecraft. No está aprobado ni asociado con Mojang, Microsoft ni los proyectos o comunidades enlazados.</p></div>
  <nav class="section-links" aria-label="Secciones de términos"><a href="#terms-use">Uso</a><a href="#terms-account">Cuenta</a><a href="#terms-privacy">Privacidad</a><a href="#terms-credits">Créditos</a><a href="#terms-funding">Financiación</a><a href="#terms-contact">Contacto</a></nav>

  <section id="terms-use"><h3><UiIcon name="book" size={20}/>1. Uso y derechos sobre Minecraft</h3><p>El launcher organiza instalaciones y facilita herramientas y enlaces. No concede una licencia de Minecraft ni sustituye su compra o las condiciones de Mojang y Microsoft. Utiliza únicamente copias y contenidos para los que tengas los derechos necesarios y respeta las normas de los servidores.</p><p>Minecraft, sus gráficos y sus marcas pertenecen a sus titulares. Leer recursos de una instalación local para mostrarlos en el equipo del usuario no transfiere su propiedad ni autoriza cualquier reutilización, publicidad o redistribución. Las capturas que el usuario consulta desde su propia carpeta siguen sujetas a los derechos y reglas aplicables a su contenido.</p><p>El código propio de esta distribución se ofrece bajo GPL-3.0-only, según el archivo LICENSE del proyecto. Esa licencia no relicencia Minecraft, mods, logos, skins ni otros materiales de terceros.</p><div class="links"><a href="https://www.minecraft.net/en-us/eula" onclick={event=>visit(event,'https://www.minecraft.net/en-us/eula')}>EULA de Minecraft<UiIcon name="external" size={13}/></a><a href="https://www.minecraft.net/en-us/usage-guidelines" onclick={event=>visit(event,'https://www.minecraft.net/en-us/usage-guidelines')}>Pautas de uso de Minecraft<UiIcon name="external" size={13}/></a></div></section>
  <section id="terms-account"><h3><UiIcon name="user" size={20}/>2. Cuenta Microsoft y perfiles locales</h3><p>El inicio de sesión abre el servicio de Microsoft mediante OAuth con el identificador de aplicación propio del proyecto. La contraseña se introduce en Microsoft, no en un campo del launcher. La autenticación continúa con Xbox y Minecraft Services para consultar el perfil y los permisos de la cuenta.</p><p>En Windows, los tokens de sesión guardados se protegen con DPAPI para el usuario del sistema. Los tokens permiten renovar una sesión sin volver a escribir la contraseña; protege también el acceso a tu cuenta de Windows y cierra la sesión del launcher en equipos compartidos.</p><p>Un perfil local con nick sirve para pruebas locales sin autenticación Microsoft. No acredita una compra, no obtiene identidad premium y no permite autenticarse en servidores que exigen una cuenta oficial. El usuario debe contar con los derechos necesarios sobre el juego y sus recursos. Mostrar la skin pública de un nick tampoco demuestra propiedad sobre esa cuenta.</p></section>
  <section id="terms-privacy"><h3><UiIcon name="shield" size={20}/>3. Datos y privacidad</h3><div class="privacy-grid"><article><h4>En el equipo</h4><p>Preferencias, perfiles, instalaciones, poses, diseños del HUD, cachés y registros se guardan en el dispositivo, normalmente bajo AppData\Roaming\MinecraftTPS. La galería lee las carpetas de capturas de las instalaciones. Consultar una captura o un mundo no lo publica automáticamente.</p></article><article><h4>Conexiones necesarias</h4><p>Microsoft, Xbox y Minecraft reciben las solicitudes de inicio de sesión y perfil. Mojang y los servicios de skins configurados pueden recibir un nick o UUID para buscar una skin. Modrinth, CurseForge, TP API y otros proveedores reciben las búsquedas, identificadores o descargas que les solicitas y pueden observar tu dirección IP.</p></article><article><h4>Enlaces y servicios externos</h4><p>Las herramientas de Comunidad se abren en el navegador. Sus sitios tienen políticas independientes. Los iconos de servicios pueden consultarse al proveedor de favicons configurado, comunicando el dominio solicitado y los datos de conexión.</p></article><article><h4>Publicación y diagnóstico</h4><p>Al publicar un servidor, su dirección y los campos del formulario se envían al directorio TP API para su consulta pública. Los registros de juego pueden contener nombres, direcciones y rutas locales: revísalos antes de copiarlos o compartirlos. Las acciones de exportar o compartir archivos requieren una acción del usuario.</p></article></div><p>Cerrar la sesión permite retirar la sesión guardada desde el gestor de cuentas. Los datos locales y las cachés permanecen hasta que los elimines; algunos son necesarios para conservar tus instalaciones. Para consultas, correcciones o solicitudes relacionadas con TP API, utiliza el contacto de TP LABS. Los plazos y las políticas de los servicios externos dependen de sus propios responsables.</p></section>
  <section id="terms-credits"><h3><UiIcon name="plugins" size={20}/>4. Proyectos, marcas y licencias</h3><p>Los nombres y símbolos identifican compatibilidad, procedencia o enlaces a sus creadores. No representan patrocinio. El carácter abierto de un programa o el acceso a su API no concede automáticamente derechos de marca. Cualquier autorización específica pendiente debe resolverse antes de los usos que la requieran.</p><div class="credits-grid">{#each credits as credit}<article><a href={credit.url} onclick={event=>visit(event,credit.url)}>{credit.name}<UiIcon name="external" size={13}/></a><p>{credit.detail}</p></article>{/each}</div><p>Los enlaces de Comunidad también incluyen Misode, Minecraft Tools, GamerGeeks, Modpack Index y McSrvStat. Sus herramientas y marcas pertenecen a sus respectivos titulares. TP LAUNCHER no incorpora sus aplicaciones ni las presenta como propias.</p><details ontoggle={loadNotices}><summary>Leer los avisos completos incluidos en esta distribución</summary><pre>{loading?'Cargando avisos…':notices}</pre></details></section>
  <section id="terms-funding"><h3><UiIcon name="server" size={20}/>5. Catálogo gratuito, patrocinio y hosting</h3><p>La consulta del catálogo público TP API es gratuita y está sujeta a disponibilidad, caché y límites de uso. No es un registro de todos los servidores de Minecraft y una ficha no acredita la seguridad de un servidor. Añadirlo a tu lista personal requiere que tú lo elijas.</p><p>El proyecto puede incorporar espacios pequeños de patrocinio o enlaces de afiliado de hosting, identificados expresamente junto al enlace. Cuando exista un acuerdo activo y el proveedor lo confirme, una compra mediante ese enlace podría generar una comisión sin un coste adicional atribuible al enlace; el precio final y el contrato dependen del proveedor.</p><p>Un enlace informativo por sí solo no constituye una colaboración ni garantiza descuentos. La posibilidad de financiación no acredita permisos de marca ni una aprobación de Mojang; cualquier campaña debe cumplir las condiciones de cada titular y la normativa aplicable.</p></section>
  <section id="terms-contact"><h3><UiIcon name="users" size={20}/>6. Contacto de TP LABS</h3><p>Proyecto TP LABS · <strong>xZaneXad / Fariiuh</strong> · Lead Dev · TP LABS. Para soporte, privacidad, atribuciones o solicitudes de titulares de derechos:</p><div class="contact-grid"><a href="https://www.instagram.com/tp_labs07/" onclick={event=>visit(event,'https://www.instagram.com/tp_labs07/')}><span class="contact-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17 7h.01"/></svg></span><span><strong>TP LABS</strong><small>Instagram · @tp_labs07</small></span><UiIcon name="external" size={15}/></a><a href="https://github.com/tomaap07" onclick={event=>visit(event,'https://github.com/tomaap07')}><span class="contact-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5-5 7 5 7m8-14 5 7-5 7m-3-16-2 20"/></svg></span><span><strong>tomaap07</strong><small>GitHub · código y contribuciones</small></span><UiIcon name="external" size={15}/></a><div class="email-contact"><a href={`mailto:${email}`} onclick={event=>visit(event,`mailto:${email}`)}><span class="contact-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/></svg></span><span><strong>Correo de contacto</strong><small>{email}</small></span></a><button onclick={copyEmail} aria-label="Copiar correo de TP LABS" title="Copiar correo"><UiIcon name="copy" size={17}/></button></div></div></section>
  {#if message}<p class="message" role="status">{message}</p>{/if}
  <p class="closing">Esta página explica el funcionamiento y atribuciones del proyecto; no certifica permisos generales sobre materiales de terceros. Si detectas un problema de derechos, incluye el recurso y su ubicación al contactar.</p>
</div>

